315	    }
316	
317	    /**
318	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two fiscal-year
319	     * digits of the owner's {@link #getMemberId() member id} (its {@code FY} segment, the two
320	     * characters following the leading region). The fiscal year starts on 1 July and is named by the
321	     * calendar year in which it ends, so a registration date on or after 1 July belongs to the
322	     * following calendar year's fiscal year (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an
323	     * earlier date stays in the current one (e.g. {@code 2026-06-15} is {@code 'FY26'}). Before the
324	     * member id has been assigned it falls back to the fiscal year of the
325	     * {@link #getRegistrationDate() business-day-adjusted registration date}. Returns {@code null}
326	     * when neither a member id nor a registration date is available.
327	     *
328	     * @return the fiscal year, or {@code null} when it cannot be derived
329	     */
330	    public String getFiscalYear() {
331	        if (this.memberId != null) {
332	            String region = leadingRegion(this.memberId);
333	            if (this.memberId.length() >= region.length() + 2) {
334	                return "FY" + this.memberId.substring(region.length(), region.length() + 2);
335	            }
336	        }
337	        if (this.registrationDate == null) {
338	            return null;
339	        }
340	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
341	    }
342	
343	    /**
344	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
345	     * is named by the calendar year in which it ends: a date in July through December belongs to the
346	     * next calendar year's fiscal year, while January through June stays in the current one.
347	     *
348	     * @param date the date to classify
349	     * @return the fiscal year as a four-digit calendar year
350	     */
351	    private static int fiscalYearOf(LocalDate date) {
352	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
353	    }
354	
355	    /**
356	     * The single Luhn check digit (0-9) computed over the digits contained in the given value.
357	     * Non-digit characters (such as the letter region and hex characters) are ignored. This is the
358	     * {@code CHK} segment of the {@link #getMemberId() member id}, computed over the digits of its
359	     * {@code <REGION><FY><HASH8>} prefix.
360	     *
361	     * @param value the value whose digits the check digit is computed over
362	     * @return the Luhn check digit
363	     */
364	    private static int luhnCheckDigit(String value) {
365	        int sum = 0;
366	        boolean dbl = true;
367	        for (int i = value.length() - 1; i >= 0; i--) {
368	            char c = value.charAt(i);
369	            if (c < '0' || c > '9') {
370	                continue;
371	            }
372	            int d = c - '0';
373	            if (dbl) {
374	                d *= 2;
375	                if (d > 9) {
376	                    d -= 9;
377	                }
378	            }
379	            sum += d;
380	            dbl = !dbl;
381	        }
382	        return (10 - (sum % 10)) % 10;
383	    }
384	
385	    /**
386	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
387	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
388	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
389	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
390	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
391	     * tenure, the tenure points are never awarded at create time.
392	     *
393	     * @return the membership points, a non-negative integer
394	     */
395	    public Integer getMembershipPoints() {
396	        int points = 0;
397	        boolean hasEmail = this.email != null && !this.email.isBlank();
398	        if (hasEmail) {
399	            points += 2;
400	        }
401	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
402	        if (hasNoNamesakes) {
403	            points += 1;
404	        }
405	        if (this.householdSize != null && this.householdSize >= 3) {
406	            points += 2;
407	        }
408	        Long tenureFiscalYears = getTenureFiscalYears();
409	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
410	            points += 3;
411	        }
412	        return points;
413	    }
414	
415	    /**
416	     * The owner's numeric membership level. This is normally derived from the
417	     * {@link #getMembershipPoints() membership points} (see {@link #deriveMembershipLevel()}), but a
418	     * household-level cap applied at create time may store a lower value here; when such a capped level
419	     * has been stored it is returned in preference to the derived one.
420	     *
421	     * @return the membership level, an integer from 1 to 4
422	     */
423	    public Integer getMembershipLevel() {
424	        if (this.membershipLevel != null) {
425	            return this.membershipLevel;
426	        }
427	        return deriveMembershipLevel();
428	    }
429	
430	    public void setMembershipLevel(Integer membershipLevel) {
431	        this.membershipLevel = membershipLevel;
432	    }
433	
434	    /**
435	     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
436	     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
437	     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
438	     *
439	     * @return the derived membership level, an integer from 1 to 4
440	     */
441	    public Integer deriveMembershipLevel() {
442	        int points = getMembershipPoints();
443	        if (points <= 1) {
444	            return 1;
445	        }
446	        if (points <= 3) {
447	            return 2;
448	        }
449	        if (points <= 5) {
450	            return 3;
451	        }
452	        return 4;
453	    }
454	
455	    /**
456	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
457	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
458	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
459	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
460	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
461	     * yet.
462	     *
463	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
464	     */
465	    public Long getTenureFiscalYears() {
466	        if (this.registrationDate == null) {
467	            return null;
468	        }
469	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
470	    }
471	
472	    /**
473	     * The owner's locality, the canonical region string. Once the owner has a
474	     * {@link #getMemberId() member id} the locality is the {@code <REGION>} component of that id (its
475	     * leading run of letters, before the fiscal-year digits), so the locality and the identity share a
476	     * single source of truth. Before the member id is assigned (for example while a create is still
477	     * validating the postcode) it falls back to the region the id will be built from: the
478	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
479	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
480	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
481	     *
482	     * @return the canonical region string, or {@code 'UNKNOWN'}
483	     */
484	    public String getLocality() {
485	        if (this.memberId != null) {
486	            return leadingRegion(this.memberId);
487	        }
488	        return deriveRegion();
489	    }
490	
491	    /**
492	     * The leading region component of a {@link #getMemberId() member id}: its leading run of letters,
493	     * which ends at the first fiscal-year digit. The member id has no separators, so the region is the
494	     * alphabetic prefix (e.g. {@code 'NSW'} or {@code 'UNKNOWN'}) that precedes the {@code <FY>} digits.
495	     *
496	     * @param memberId the member id to read the region from
497	     * @return the leading region string
498	     */
499	    private static String leadingRegion(String memberId) {
500	        int end = 0;
501	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
502	            end++;
503	        }
504	        return memberId.substring(0, end);
505	    }
506	
507	    /**
508	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
509	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
510	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
511	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
512	     *
513	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
514	     */
515	    public String getTimezone() {
516	        return REGION_TIMEZONE.get(getLocality());
517	    }
518	
519	    /**
520	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
521	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER}
522	     * is {@code 'PREMIUM'} when the {@link #getMembershipLevel() membership level} is 3 or more,
523	     * otherwise {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the {@link #getLocality()
524	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
525	     *
526	     * @return the owner segment string
527	     */
528	    public String getOwnerSegment() {
529	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
530	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
531	        return tier + "_" + area;
532	    }
533	
534	    /**
535	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
536	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
537	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
538	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
539	     * the same region for known cities but disambiguates cities that share a name.
540	     *
541	     * @return the canonical region string, or {@code 'UNKNOWN'}
542	     */
543	    private String deriveRegion() {
544	        String region = regionFromPostcode();
545	        if (region != null) {
546	            return region;
547	        }
548	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
549	    }
550	
551	    /**
552	     * Builds this owner's member id, formatted {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is
553	     * the region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
554	     * {@link #deriveRegion()}); {@code FY} is the two-digit fiscal year of the
555	     * {@link #getRegistrationDate() registration date} (the fiscal year starts on 1 July; see
556	     * {@link #fiscalYearOf(LocalDate)}); {@code HASH8} is the first 8 upper-case hexadecimal
557	     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with its last
558	     * name (the same hash the region-and-hash identity uses); and {@code CHK} is a single Luhn check
559	     * digit over the digits of the {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW261A2B3C4D7'}).
560	     * It carries no sequence number, so it is a pure function of the owner's region, fiscal year,
561	     * telephone and last name. Call this once at create time and store the result via
562	     * {@link #setMemberId(String)}, which thereafter backs {@link #getLocality()} and
563	     * {@link #getFiscalYear()}.
564	     *
565	     * @return the assembled member id
566	     */
567	    public String buildMemberId() {
568	        String base = deriveRegion()
569	            + String.format("%02d", fiscalYearOf(this.registrationDate) % 100)
570	            + sha256Hex8(this.telephone + this.getLastName());
571	        return base + luhnCheckDigit(base);
572	    }
573	
574	    /**
575	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
576	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
577	     *
578	     * @param value the value to hash
579	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
580	     */
581	    private static String sha256Hex8(String value) {
582	        try {
583	            byte[] digest = MessageDigest.getInstance("SHA-256")
584	                .digest(value.getBytes(StandardCharsets.UTF_8));
585	            StringBuilder hex = new StringBuilder(8);
586	            for (int i = 0; i < 4; i++) {
587	                hex.append(String.format("%02X", digest[i]));
588	            }
589	            return hex.toString();
590	        }
591	        catch (NoSuchAlgorithmException e) {
592	            throw new IllegalStateException("SHA-256 algorithm not available", e);
593	        }
594	    }
595	
596	    /**
597	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
598	     * absent, not a 4-digit number, or in no known range.
599	     *
600	     * @return the matching region, or {@code null}
601	     */
602	    private String regionFromPostcode() {
603	        if (this.postcode == null) {
604	            return null;
605	        }
606	        int value;
607	        try {
608	            value = Integer.parseInt(this.postcode.trim());
609	        }
610	        catch (NumberFormatException ex) {
611	            return null;
612	        }
613	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
614	            int[] range = entry.getValue();
615	            if (value >= range[0] && value <= range[1]) {
616	                return entry.getKey();
617	            }
618	        }
619	        return null;
620	    }
621	
622	    /**
623	     * The owner's preferred contact channel, derived from the owner's details. Returns
624	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
625	     *
626	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
627	     */
628	    public String getContactPreference() {
629	        boolean hasEmail = this.email != null && !this.email.isBlank();
630	        return hasEmail ? "EMAIL" : "PHONE";
631	    }
632	
633	    /**
634	     * The owner's identity key, the single derived value used for duplicate detection. It is the
635	     * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
636	     * email (empty when absent) and the {@linkplain Soundex#encode(String) Soundex} of its last name,
637	     * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
638	     * absent ({@code null}) component contributes an empty string before hashing. Two owners are
639	     * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
640	     * (and its Soundex) and postcode but carrying different telephones differ here and are both
641	     * allowed (the second is flagged a soft match rather than rejected).
642	     *
643	     * @return the derived identity key, a 64-character lower-case hex string
644	     */
645	    public String getIdentityKey() {
646	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
647	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
648	        String raw = normalizedTelephone + "|" + lowerEmail + "|" + Soundex.encode(this.getLastName());
649	        return sha256HexLower(raw);
650	    }
651	
652	    /**
653	     * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
654	     * form the {@linkplain #getIdentityKey() identity key} takes.
655	     *
656	     * @param value the value to hash
657	     * @return the 64-character lower-case hex SHA-256 digest
658	     */
659	    private static String sha256HexLower(String value) {
660	        try {
661	            byte[] digest = MessageDigest.getInstance("SHA-256")
662	                .digest(value.getBytes(StandardCharsets.UTF_8));
663	            StringBuilder hex = new StringBuilder(digest.length * 2);
664	            for (byte b : digest) {
665	                hex.append(String.format("%02x", b));
666	            }
667	            return hex.toString();
668	        }
669	        catch (NoSuchAlgorithmException e) {
670	            throw new IllegalStateException("SHA-256 algorithm not available", e);
671	        }
672	    }
673	
674	    public String getHouseholdId() {
675	        return this.householdId;
676	    }
677	
678	    public void setHouseholdId(String householdId) {
679	        this.householdId = householdId;
680	    }
681	
682	    public Integer getNamesakeCount() {
683	        return this.namesakeCount;
684	    }
685	
686	    public void setNamesakeCount(Integer namesakeCount) {
687	        this.namesakeCount = namesakeCount;
688	    }
689	
690	    public Integer getHouseholdSize() {
691	        return this.householdSize;
692	    }
693	
694	    public void setHouseholdSize(Integer householdSize) {
695	        this.householdSize = householdSize;
696	    }
697	
698	    public String getPostcode() {
699	        return this.postcode;
700	    }
701	
702	    public void setPostcode(String postcode) {
703	        this.postcode = postcode;
704	    }
705	
706	    public Boolean getBulkSignupWarning() {
707	        return this.bulkSignupWarning;
708	    }
709	
710	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
711	        this.bulkSignupWarning = bulkSignupWarning;
712	    }
713	
714	    public Boolean getCapacityWarning() {
715	        return this.capacityWarning;
716	    }
717	
718	    public void setCapacityWarning(Boolean capacityWarning) {
719	        this.capacityWarning = capacityWarning;
720	    }
721	
722	    public Boolean getPossibleDuplicate() {
723	        return this.possibleDuplicate;
724	    }
725	
726	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
727	        this.possibleDuplicate = possibleDuplicate;
728	    }
729	
730	    public Integer getPossibleDuplicateOf() {
731	        return this.possibleDuplicateOf;
732	    }
733	
734	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
735	        this.possibleDuplicateOf = possibleDuplicateOf;
736	    }
737	
738	    /**
739	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
740	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
741	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
742	     *
743	     * @return whether the owner has been soft-deleted
744	     */
745	    public boolean isDeleted() {
746	        return this.deleted;
747	    }
748	
749	    public void setDeleted(boolean deleted) {
750	        this.deleted = deleted;
751	    }
752	
753	    /**
754	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
755	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
756	     */
757	    @PrePersist
758	    void onCreate() {
759	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
760	    }
761	
762	    /**
763	     * Resolves the effective registration date and rolls it onto a business day. An absent
764	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
765	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
766	     * holiday: starting from the effective date, the date advances one day at a time while it lands
767	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
768	     * non-holiday business day. A date already on a business day is returned unchanged.
769	     *
770	     * <p>This is the single definition of both the defaulting and the business-day roll, used
771	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
772	     * stamps the owner and by the create endpoint that counts owners per business day.
773	     *
774	     * @param supplied the registration date from the request, or {@code null} when none was supplied
775	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
776	     */
777	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
778	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
779	        while (!isBusinessDay(effective)) {
780	            effective = effective.plusDays(1);
781	        }
782	        return effective;
783	    }
784	
785	    /**
786	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
787	     */
788	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
789	        LocalDate.of(2026, 1, 1),
790	        LocalDate.of(2026, 1, 26),
791	        LocalDate.of(2026, 4, 25),
792	        LocalDate.of(2026, 12, 25),
793	        LocalDate.of(2026, 12, 28));
794	
795	    /**
796	     * A business day is any date that is neither a weekend day nor a listed public holiday.
797	     */
798	    private static boolean isBusinessDay(LocalDate date) {
799	        DayOfWeek day = date.getDayOfWeek();
800	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
801	    }
802	
803	    protected Set<Pet> getPetsInternal() {
804	        if (this.pets == null) {
805	            this.pets = new HashSet<>();
806	        }
807	        return this.pets;
808	    }
809	
810	    protected void setPetsInternal(Set<Pet> pets) {
811	        this.pets = pets;
812	    }
813	
814	    public List<Pet> getPets() {
815	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
816	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
817	        return Collections.unmodifiableList(sortedPets);
818	    }
819	
820	    public void setPets(List<Pet> pets) {
821	        this.pets = new HashSet<>(pets);
822	    }
823	
824	    public void addPet(Pet pet) {
825	        getPetsInternal().add(pet);
826	        pet.setOwner(this);
827	    }
828	
829	    /**
830	     * Return the Pet with the given name, or null if none found for this Owner.
831	     *
832	     * @param name to test
833	     * @return true if pet name is already in use
834	     */
835	    public Pet getPet(String name) {
836	        return getPet(name, false);
837	    }
838	
839	    /**
840	     * Return the Pet with the given name, or null if none found for this Owner.
841	     *
842	     * @param name to test
843	     * @return true if pet name is already in use
844	     */
845	    public Pet getPet(String name, boolean ignoreNew) {
846	        name = name.toLowerCase();
847	        for (Pet pet : getPetsInternal()) {
848	            if (!ignoreNew || !pet.isNew()) {
849	                String compName = pet.getName();
850	                compName = compName.toLowerCase();
851	                if (compName.equals(name)) {
852	                    return pet;
853	                }
854	            }
855	        }
856	        return null;
857	    }
858	
859	    public Pet getPet(Integer petId) {
860	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
861	    }
862	
863	    @Override
864	    public String toString() {
865	        return new ToStringCreator(this)
866	
867	            .append("id", this.getId())
868	            .append("new", this.isNew())
869	            .append("lastName", this.getLastName())
870	            .append("firstName", this.getFirstName())
871	            .append("address", this.address)
872	            .append("city", this.city)
873	            .append("telephone", this.telephone)
874	            .toString();
875	    }
876	}
