229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
232	        String idempotencyKey = currentIdempotencyKey();
233	        OwnerDto replayed = replayIfSeen(idempotencyKey);
234	        if (replayed != null) {
235	            return new ResponseEntity<>(replayed, HttpStatus.OK);
236	        }
237	        validateRequiredFields(ownerFieldsDto);
238	        HttpHeaders headers = new HttpHeaders();
239	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
240	        rejectFutureRegistrationDate(owner.getRegistrationDate());
241	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
242	        owner.setRegistrationDate(registrationDate);
243	        requireDailyCapacity(registrationDate);
244	        long cityOwnerCount = countOwnersInCity(owner.getCity());
245	        requireCityHasCapacity(owner.getCity(), cityOwnerCount);
246	        owner.setCapacityWarning(isApproachingCityCapacity(cityOwnerCount));
247	        validatePostcode(owner);
248	        applyAddress(owner, ownerFieldsDto);
249	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
250	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
251	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
252	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
253	        requireUniqueIdentity(owner);
254	        flagPossibleDuplicate(owner, declaredHouseholdMember);
255	        owner.setMemberId(deduplicateMemberId(owner.buildMemberId()));
256	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
257	        stampHouseholdSize(owner);
258	        capMembershipLevelToHousehold(owner);
259	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
260	        this.clinicService.saveOwner(owner);
261	        rememberCreate(idempotencyKey, owner);
262	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
263	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
264	        emitOwnerCreatedEvent(owner);
265	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
266	        headers.setLocation(UriComponentsBuilder.newInstance()
267	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
268	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
269	    }
