271	    /**
272	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@link #AUDIT} logger as a
273	     * compact JSON object, alongside the human-readable audit line. The event's {@code seq} is drawn
274	     * from the process-wide {@link #AUDIT_SEQUENCE}, so it strictly increases across creates, and it
275	     * carries both the owner's id and its current primary identifier via
276	     * {@link #primaryIdentifier(Owner)}.
277	     *
278	     * @param owner the owner that was just created and saved
279	     */
280	    private void emitOwnerCreatedEvent(Owner owner) {
281	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(),
282	            owner.getId(), owner.getMemberId(), owner.getMembershipLevel());
283	        AUDIT.info(event.toJson());
284	    }
285	
286	    /**
287	     * The immutable structured event emitted on a successful owner create. {@code seq} is the
288	     * process-wide monotonically increasing sequence across creates; {@code ownerId} is the new
289	     * owner's id; {@code memberId} carries the owner's unified member id; {@code membershipLevel} is
290	     * the owner's membership level. It serializes to a compact JSON object whose {@code event} is
291	     * always {@value #EVENT_TYPE}.
292	     *
293	     * @param seq the monotonically increasing create sequence number
294	     * @param ownerId the created owner's id
295	     * @param memberId the owner's unified member id
296	     * @param membershipLevel the owner's membership level
297	     */
298	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel) {
299	
300	        /** The fixed {@code event} discriminator carried by every emitted event. */
301	        private static final String EVENT_TYPE = "OWNER_CREATED";
302	
303	        /** Shared, thread-safe mapper used only to serialize the event to its JSON form. */
304	        private static final ObjectMapper MAPPER = JsonMapper.builder().build();
305	
306	        /**
307	         * Serializes this event to its compact JSON form
308	         * {@code {seq, ownerId, memberId, membershipLevel, event}}, with the fields in that order.
309	         *
310	         * @return the event as a JSON object string
311	         */
312	        private String toJson() {
313	            Map<String, Object> fields = new LinkedHashMap<>();
314	            fields.put("seq", this.seq);
315	            fields.put("ownerId", this.ownerId);
316	            fields.put("memberId", this.memberId);
317	            fields.put("membershipLevel", this.membershipLevel);
318	            fields.put("event", EVENT_TYPE);
319	            return MAPPER.writeValueAsString(fields);
320	        }
321	    }
322	
323	    /**
324	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
325	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
326	     * or when no servlet request is bound to the current thread.
327	     *
328	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
329	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
330	     * interface and cannot carry an extra parameter.
331	     *
332	     * @return the trimmed idempotency key, or {@code null} when none was supplied
333	     */
334	    private String currentIdempotencyKey() {
335	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
336	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
337	            if (StringUtils.hasText(key)) {
338	                return key.trim();
339	            }
340	        }
341	        return null;
342	    }
343	
344	    /**
345	     * Returns the owner originally created under the given idempotency key, so a create repeating a
346	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
347	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
348	     * which case the create proceeds normally).
349	     *
350	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
351	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
352	     */
353	    private OwnerDto replayIfSeen(String idempotencyKey) {
354	        if (idempotencyKey == null) {
355	            return null;
356	        }
357	        Integer existingId = idempotentCreates.get(idempotencyKey);
358	        if (existingId == null) {
359	            return null;
360	        }
361	        Owner existing = this.clinicService.findOwnerById(existingId);
362	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
363	    }
364	
365	    /**
366	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
367	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
368	     * create was not idempotent) is ignored.
369	     *
370	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
371	     * @param owner the owner that was just created and saved
372	     */
373	    private void rememberCreate(String idempotencyKey, Owner owner) {
374	        if (idempotencyKey != null) {
375	            idempotentCreates.put(idempotencyKey, owner.getId());
376	        }
377	    }
