379	    /**
380	     * Rejects a create whose supplied registration date is later than the server's current date. A
381	     * registration may be back-dated but never post-dated, so a future date is treated as a client
382	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
383	     * server date.
384	     *
385	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
386	     *     client omitted it
387	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
388	     */
389	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
390	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
391	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
392	        }
393	    }
394	
395	    /**
396	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
397	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
398	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
399	     * existed prior to this create.
400	     *
401	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
402	     *     a business day
403	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
404	     *     registered on that business day
405	     */
406	    private void requireDailyCapacity(LocalDate registrationDate) {
407	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
408	            throw new DailyOwnerLimitException(registrationDate);
409	        }
410	    }
411	
412	    /**
413	     * Counts the existing owners whose registration date equals the given business-day date. This is
414	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
415	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
416	     * the bulk-signup warning.
417	     *
418	     * @param registrationDate the effective business-day registration date to count against
419	     * @return the number of pre-existing owners registered on that date
420	     */
421	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
422	        return this.clinicService.findAllOwners().stream()
423	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
424	            .count();
425	    }
426	
427	    /**
428	     * Rejects an owner whose city already contains the maximum allowed number of owners
429	     * ({@value #MAX_OWNERS_PER_CITY}). The count is supplied by {@link #countOwnersInCity(String)} and
430	     * reflects only the owners that existed prior to this create.
431	     *
432	     * @param city the city of the owner being created
433	     * @param cityOwnerCount the number of pre-existing owners already in that city
434	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
435	     */
436	    private void requireCityHasCapacity(String city, long cityOwnerCount) {
437	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
438	            throw new CityOwnerLimitException(city);
439	        }
440	    }
441	
442	    /**
443	     * Counts the existing owners whose city equals the given city, compared case-insensitively. This is
444	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to this
445	     * create. It is the single definition of the per-city count shared by the city hard-limit rule and
446	     * the approaching-capacity warning.
447	     *
448	     * @param city the city of the owner being created
449	     * @return the number of pre-existing owners in that city
450	     */
451	    private long countOwnersInCity(String city) {
452	        return this.clinicService.findAllOwners().stream()
453	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
454	            .count();
455	    }
456	
457	    /**
458	     * Whether a city holding the given number of owners is approaching the per-city capacity limit: at
459	     * least {@value #CITY_CAPACITY_WARNING_THRESHOLD} but fewer than {@value #MAX_OWNERS_PER_CITY}. A
460	     * create in such a city is flagged ({@code capacityWarning} true); the hard rejection at
461	     * {@value #MAX_OWNERS_PER_CITY} is unaffected.
462	     *
463	     * @param cityOwnerCount the number of pre-existing owners already in the city
464	     * @return whether the city is in the 40-49 approaching-capacity band
465	     */
466	    private boolean isApproachingCityCapacity(long cityOwnerCount) {
467	        return cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD && cityOwnerCount < MAX_OWNERS_PER_CITY;
468	    }
469	
470	    /**
471	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
472	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
473	     * schema) that must fall within the inclusive range permitted for the region derived from the
474	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
475	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
476	     *
477	     * @param owner the owner being created, with its city and postcode set
478	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
479	     */
480	    private void validatePostcode(Owner owner) {
481	        String postcode = owner.getPostcode();
482	        if (postcode == null) {
483	            return;
484	        }
485	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
486	        if (range == null) {
487	            return;
488	        }
489	        int value = Integer.parseInt(postcode);
490	        if (value < range[0] || value > range[1]) {
491	            throw new InvalidOwnerFieldsException(List.of("postcode"));
492	        }
493	    }
494	
495	    /**
496	     * Counts the existing owners that already share the given first name and last name, compared
497	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
498	     * owners that existed prior to this create.
499	     *
500	     * @param firstName the first name of the owner being created
501	     * @param lastName the last name of the owner being created
502	     * @return the number of pre-existing namesakes
503	     */
504	    private int countNamesakes(String firstName, String lastName) {
505	        return (int) this.clinicService.findAllOwners().stream()
506	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
507	                && equalsIgnoreCase(existing.getLastName(), lastName))
508	            .count();
509	    }
510	
511	    /**
512	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
513	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
514	     *
515	     * @param a the first value, possibly {@code null}
516	     * @param b the second value, possibly {@code null}
517	     * @return whether the values are equal ignoring case
518	     */
519	    private boolean equalsIgnoreCase(String a, String b) {
520	        return a == null ? b == null : a.equalsIgnoreCase(b);
521	    }
522	
523	    /**
524	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
525	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
526	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
527	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
528	     *
529	     * @param ownerFieldsDto the submitted owner fields
530	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
531	     */
532	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
533	        List<String> invalidFields = new ArrayList<>();
534	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
535	            invalidFields.add("firstName");
536	        }
537	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
538	            invalidFields.add("lastName");
539	        }
540	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
541	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
542	            invalidFields.add("address");
543	        }
544	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
545	            invalidFields.add("city");
546	        }
547	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
548	            invalidFields.add("telephone");
549	        }
550	        if (!invalidFields.isEmpty()) {
551	            throw new InvalidOwnerFieldsException(invalidFields);
552	        }
553	    }
554	
555	    /**
556	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
557	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
558	     * what gets stored and returned.
559	     *
560	     * @param telephone the raw telephone value from the request
561	     * @return the normalized E.164 telephone number
562	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
563	     */
564	    private String normalizeTelephone(String telephone) {
565	        String e164 = toE164(telephone);
566	        if (e164 == null) {
567	            throw new InvalidOwnerFieldsException(List.of("telephone"));
568	        }
569	        return e164;
570	    }
571	
572	    /**
573	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
574	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
575	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
576	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
577	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
578	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
579	     *
580	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
581	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
582	     *
583	     * @param telephone the raw telephone value, possibly {@code null}
584	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
585	     */
586	    private String toE164(String telephone) {
587	        if (telephone == null) {
588	            return null;
589	        }
590	        String cleaned = telephone.replaceAll("[ \\-()]", "");
591	        String digits;
592	        if (cleaned.startsWith("+")) {
593	            digits = cleaned.substring(1);
594	        } else {
595	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
596	            digits = "61" + national;
597	        }
598	        if (!digits.matches("[0-9]{8,15}")) {
599	            return null;
600	        }
601	        if (!nationalNumberLengthValid(digits)) {
602	            return null;
603	        }
604	        return "+" + digits;
605	    }
606	
607	    /**
608	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
609	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
610	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
611	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
612	     * accepted, leaving only the generic total-length rule to apply.
613	     *
614	     * @param digits the E.164 digits without the leading {@code '+'}
615	     * @return {@code true} if the national-number length matches the country code's requirement
616	     */
617	    private boolean nationalNumberLengthValid(String digits) {
618	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
619	            String code = entry.getKey();
620	            if (digits.startsWith(code)) {
621	                return digits.length() - code.length() == entry.getValue();
622	            }
623	        }
624	        return true;
625	    }
626	
627	    /**
628	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
629	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
630	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
631	     * returned lower-cased.
632	     *
633	     * @param email the raw email value from the request, possibly {@code null}
634	     * @return the lower-cased email, or {@code null} when none was supplied
635	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
636	     *     its domain is on the disposable-domain blocklist
637	     */
638	    private String normalizeEmail(String email) {
639	        if (!StringUtils.hasText(email)) {
640	            return null;
641	        }
642	        String trimmed = email.trim();
643	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
644	            throw new InvalidOwnerFieldsException(List.of("email"));
645	        }
646	        String normalized = trimmed.toLowerCase(Locale.ROOT);
647	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
648	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
649	            throw new InvalidOwnerFieldsException(List.of("email"));
650	        }
651	        return normalized;
652	    }
653	
654	    /**
655	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
656	     * This is the single consolidated duplicate check: the identity key
657	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
658	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
659	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
660	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
661	     * but carrying different telephones have different identity keys and are both allowed (the second
662	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
663	     *
664	     * @param owner the owner being created, with its normalized telephone, email and last name set
665	     * @throws DuplicateIdentityException if another owner already has this identity key
666	     */
667	    private void requireUniqueIdentity(Owner owner) {
668	        String identityKey = owner.getIdentityKey();
669	        boolean inUse = this.clinicService.findAllOwners().stream()
670	            .filter(existing -> !existing.isDeleted())
671	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
672	        if (inUse) {
673	            throw new DuplicateIdentityException(identityKey);
674	        }
675	    }
676	
677	    /**
678	     * De-duplicates a newly computed member id against the ids already held by existing owners. When
679	     * the computed id is unique it is returned unchanged. When it collides with an existing owner's
680	     * {@code memberId}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes
681	     * the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and so on),
682	     * and that de-duplicated id is returned.
683	     *
684	     * @param memberId the freshly computed member id to de-duplicate
685	     * @return a member id not held by any existing owner
686	     */
687	    private String deduplicateMemberId(String memberId) {
688	        Set<String> inUse = this.clinicService.findAllOwners().stream()
689	            .map(Owner::getMemberId)
690	            .filter(Objects::nonNull)
691	            .collect(Collectors.toSet());
692	        if (!inUse.contains(memberId)) {
693	            return memberId;
694	        }
695	        int n = 2;
696	        String candidate;
697	        do {
698	            candidate = memberId + "-" + n;
699	            n++;
700	        } while (inUse.contains(candidate));
701	        return candidate;
702	    }
703	
704	    /**
705	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
706	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
707	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
708	     * (both present and equal) while carrying a different identity key. When such an existing owner is
709	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
710	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
711	     * is false and {@code possibleDuplicateOf} is left unset.
712	     *
713	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
714	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
715	     *
716	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
717	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
718	     */
719	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
720	        if (declaredHouseholdMember || owner.getPostcode() == null) {
721	            owner.setPossibleDuplicate(false);
722	            return;
723	        }
724	        String identityKey = owner.getIdentityKey();
725	        String soundex = Soundex.encode(owner.getLastName());
726	        Integer matchId = this.clinicService.findAllOwners().stream()
727	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
728	                && owner.getPostcode().equals(existing.getPostcode())
729	                && !identityKey.equals(existing.getIdentityKey()))
730	            .map(Owner::getId)
731	            .min(Integer::compareTo)
732	            .orElse(null);
733	        owner.setPossibleDuplicate(matchId != null);
734	        owner.setPossibleDuplicateOf(matchId);
735	    }
736	
737	    /**
738	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
739	     * the household - the existing owners that share the deterministic {@code householdId} and the new
740	     * one - so the shared size can be read back from any of them. The count is the number of existing
741	     * members plus the owner being created.
742	     *
743	     * @param owner the owner being created, with its deterministic {@code householdId} already set
744	     */
745	    private void stampHouseholdSize(Owner owner) {
746	        List<Owner> members = householdMembers(owner);
747	        int householdSize = members.size() + 1;
748	        owner.setHouseholdSize(householdSize);
749	        for (Owner member : members) {
750	            member.setHouseholdSize(householdSize);
751	            this.clinicService.saveOwner(member);
752	        }
753	    }
754	
755	    /**
756	     * The existing owners that belong to the same household as the given owner - those that share its
757	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
758	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
759	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
760	     * only live members filter them out themselves.
761	     *
762	     * @param owner the owner being created, with its deterministic {@code householdId} already set
763	     * @return the existing same-household owners
764	     */
765	    private List<Owner> householdMembers(Owner owner) {
766	        String householdId = owner.getHouseholdId();
767	        return this.clinicService.findAllOwners().stream()
768	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
769	            .toList();
770	    }
771	
772	    /**
773	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
774	     * membership level among the existing members of its household - the non-deleted owners that share
775	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
776	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
777	     * has no existing member no cap applies and the level is left untouched.
778	     *
779	     * @param owner the owner being created, with its deterministic {@code householdId} and
780	     *     {@code householdSize} already set
781	     */
782	    private void capMembershipLevelToHousehold(Owner owner) {
783	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
784	            .filter(existing -> !existing.isDeleted())
785	            .mapToInt(Owner::getMembershipLevel)
786	            .max();
787	        if (maxMemberLevel.isEmpty()) {
788	            return;
789	        }
790	        int cap = maxMemberLevel.getAsInt() + 1;
791	        if (owner.getMembershipLevel() > cap) {
792	            owner.setMembershipLevel(cap);
793	        }
794	    }
795	
796	    /**
797	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
798	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
799	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
800	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
801	     * shares a last name and postcode computes the same identifier and therefore the same household.
802	     *
803	     * @param lastName the last name of the household
804	     * @param postcode the postcode of the household, possibly {@code null}
805	     * @return the 12-character upper-case hex household identifier
806	     */
807	    private String computeHouseholdId(String lastName, String postcode) {
808	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
809	        try {
810	            byte[] digest = MessageDigest.getInstance("SHA-256")
811	                .digest(key.getBytes(StandardCharsets.UTF_8));
812	            StringBuilder hex = new StringBuilder(12);
813	            for (int i = 0; i < 6; i++) {
814	                hex.append(String.format("%02X", digest[i]));
815	            }
816	            return hex.toString();
817	        } catch (NoSuchAlgorithmException e) {
818	            throw new IllegalStateException("SHA-256 algorithm not available", e);
819	        }
820	    }
821	
822	    /**
823	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
824	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
825	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
826	     *
827	     * @param value the raw value, possibly {@code null}
828	     * @return the normalized value
829	     */
830	    private String normalizeForHousehold(String value) {
831	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
832	    }
833	
834	    /**
835	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
836	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
837	     * value yields an empty string.
838	     *
839	     * @param value the raw value, possibly {@code null}
840	     * @return the trimmed, whitespace-collapsed value
841	     */
842	    private String collapseWhitespace(String value) {
843	        if (value == null) {
844	            return "";
845	        }
846	        return value.trim().replaceAll("\\s+", " ");
847	    }
848	
849	    /**
850	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
851	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
852	     * is upper-cased, and common street-type abbreviations are expanded as whole words
853	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
854	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
855	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
856	     *
857	     * @param address the raw address value, possibly {@code null}
858	     * @return the normalized address
859	     */
860	    private String normalizeAddress(String address) {
861	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
862	        if (collapsed.isEmpty()) {
863	            return "";
864	        }
865	        String[] tokens = collapsed.split(" ");
866	        StringBuilder normalized = new StringBuilder();
867	        for (int i = 0; i < tokens.length; i++) {
868	            if (i > 0) {
869	                normalized.append(' ');
870	            }
871	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
872	        }
873	        return normalized.toString();
874	    }
875	
876	    /**
877	     * Applies the owner's address from the request, preferring the structured form over the flat one.
878	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
879	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
880	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
881	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
882	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
883	     * the structured address when present, falling back to the flat address.
884	     *
885	     * @param owner the owner being created
886	     * @param ownerFieldsDto the submitted owner fields
887	     */
888	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
889	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
890	        if (StringUtils.hasText(line1)) {
891	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
892	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
893	            owner.setAddressLine1(line1);
894	            owner.setAddressLine2(normalizedLine2);
895	            owner.setAddress(composeAddress(line1, normalizedLine2));
896	        } else {
897	            owner.setAddressLine1(null);
898	            owner.setAddressLine2(null);
899	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
900	        }
901	    }
902	
903	    /**
904	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
905	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
906	     * appended when the second line is present.
907	     *
908	     * @param line1 the normalized first address line
909	     * @param line2 the normalized second address line, or {@code null} when absent
910	     * @return the composed address string
911	     */
912	    private String composeAddress(String line1, String line2) {
913	        return line2 == null ? line1 : line1 + " " + line2;
914	    }
915	
916	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
917	    @Override
918	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
919	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
920	        if (currentOwner == null) {
921	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
922	        }
923	        currentOwner.setAddress(ownerFieldsDto.getAddress());
924	        currentOwner.setCity(ownerFieldsDto.getCity());
925	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
926	        currentOwner.setLastName(ownerFieldsDto.getLastName());
927	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
928	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
929	        this.clinicService.saveOwner(currentOwner);
930	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
931	    }
932	
933	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
934	    @Transactional
935	    @Override
936	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
937	        Owner owner = this.clinicService.findOwnerById(ownerId);
938	        if (owner == null) {
939	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
940	        }
941	        owner.setDeleted(true);
942	        this.clinicService.saveOwner(owner);
943	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
944	    }
945	
946	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
947	    @Override
948	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
949	        Owner owner = this.clinicService.findOwnerById(ownerId);
950	        if (owner == null) {
951	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
952	        }
953	        HttpHeaders headers = new HttpHeaders();
954	        Pet pet = petMapper.toPet(petFieldsDto);
955	        owner.setId(ownerId);
956	        pet.setOwner(owner);
957	        pet.getType().setName(null);
958	        this.clinicService.savePet(pet);
959	        PetDto petDto = petMapper.toPetDto(pet);
960	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
961	            .buildAndExpand(pet.getId()).toUri());
962	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
963	    }
964	
965	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
966	    @Override
967	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
968	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
969	        if (currentOwner != null) {
970	            Pet currentPet = this.clinicService.findPetById(petId);
971	            if (currentPet != null) {
972	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
973	                currentPet.setName(petFieldsDto.getName());
974	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
975	                this.clinicService.savePet(currentPet);
976	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
977	            }
978	        }
979	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
980	    }
