982	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
983	    @Override
984	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
985	        HttpHeaders headers = new HttpHeaders();
986	        Visit visit = visitMapper.toVisit(visitFieldsDto);
987	        Pet pet = new Pet();
988	        pet.setId(petId);
989	        visit.setPet(pet);
990	        this.clinicService.saveVisit(visit);
991	        VisitDto visitDto = visitMapper.toVisitDto(visit);
992	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
993	            .buildAndExpand(visit.getId()).toUri());
994	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
