997	
998	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
999	    @Override
1000	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
1001	        Owner owner = this.clinicService.findOwnerById(ownerId);
1002	        if (owner != null) {
1003	            Pet pet = owner.getPet(petId);
1004	            if (pet != null) {
1005	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
1006	            }
1007	        }
1008	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
1009	    }
